CREATE POLICY applicant_upload ON storage.objects FOR INSERT TO anon,authenticated WITH CHECK(bucket_id='applicant-documents' AND (storage.foldername(name))[1]='submissions' AND lower(storage.extension(name)) IN ('pdf','doc','docx','jpg','jpeg','png','webp'));
CREATE POLICY applicant_admin_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='applicant-documents' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY applicant_admin_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='applicant-documents' AND public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.subscribe_platform(_email text,_name text DEFAULT '',_categories jsonb DEFAULT '[]') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE token uuid; BEGIN IF _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(_email)>254 OR length(_name)>200 OR octet_length(_categories::text)>2000 THEN RAISE EXCEPTION 'Please check your email'; END IF; INSERT INTO public.platform_subscribers(email,full_name,categories) VALUES(lower(trim(_email)),_name,_categories) ON CONFLICT(email) DO NOTHING RETURNING unsubscribe_token INTO token; RETURN token; END $$;